    const resolvedPath = path.resolve(rootPath, String(name || ""));
    const rel = path.relative(rootPath, resolvedPath);

    if (!name || rel.startsWith("..") || path.isAbsolute(rel)) {
        return res.status(400).json({ error: "Invalid file path" });
    }

